{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 쿼리의 병목에 맞는 개선 조치를 선택할 수 있는지 확인한다. 실행 계획에서 확인한 문제와 인덱스 추가·조인 정리를 선택한 근거의 연결에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 운영 화면의 신고 목록 조회 쿼리가 3.2초 걸렸다.",
          "task": "신고 목록 조회 쿼리에 인덱스를 추가하고 조인을 정리해 조회 시간을 0.4초로 줄였다.",
          "action": "실행 계획에서 확인한 전체 조인과 조회 조건을 근거로 인덱스 추가와 조인 정리를 선택한 판단을 설명한다.",
          "result": "선택한 조치가 쿼리의 병목을 줄이는 데 적절했던 이유를 설명한다."
        },
        "expectedEvidence": [
          "인덱스 추가와 조인 정리를 선택한 구체적인 근거",
          "실행 계획에서 확인한 문제와 선택한 조치 사이의 연결"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회 쿼리를 3.2초에서 0.4초로 줄이셨을 때, 인덱스 추가와 조인 정리를 선택한 근거는 무엇이었나요?",
      "answerTip": "핵심부터 말하고 구체적으로 덧붙여 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획에서 확인한 전체 조인이나 조회 조건을 짚어 개선 조치를 선택한 근거를 구체적으로 설명한다.",
            "인덱스 추가와 조인 정리가 확인한 병목을 줄이는 데 적절한 이유를 쿼리의 처리 특성과 연결한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "조회 속도를 높이려는 목적으로 인덱스 추가와 조인 정리를 선택했다고 답하지만 실제 쿼리에서 확인한 근거가 일반적이다.",
            "선택한 조치와 병목의 관계를 설명하지만 일부 조치의 타당성을 뒷받침하는 설명이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "조회 시간이 줄었다는 결과나 수행한 조치만 반복하고 선택 근거를 제시하지 못한다.",
            "인덱스나 조인의 일반적인 장점만 나열하거나 확인한 병목과 맞지 않는 근거를 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "로그로 확인한 장애 원인에 맞춰 반복 발생을 막는 수정 조치를 선택할 수 있는지 확인한다. 스케줄러 중복 실행에 잠금 키를 적용하기로 판단한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 같은 알림이 두 번 발송된다는 문의가 들어왔다.",
          "task": "시간순으로 모은 로그에서 스케줄러가 서버 두 대에서 동시에 실행되는 것을 찾아 잠금 키를 두는 방식으로 수정했다.",
          "action": "두 서버의 스케줄러 동시 실행이라는 원인에 잠금 키가 적절하다고 판단한 근거를 설명한다.",
          "result": "잠금 키가 같은 원인의 중복 발송을 막을 수 있다고 본 이유를 설명한다."
        },
        "expectedEvidence": [
          "스케줄러에 잠금 키를 두기로 판단한 구체적인 근거",
          "로그에서 확인한 동시 실행과 잠금 키의 중복 실행 방지 효과 사이의 연결"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송 오류를 고치셨을 때, 스케줄러에 잠금 키를 두기로 판단한 근거는 무엇이었나요?",
      "answerTip": "핵심부터 말하고 구체적으로 덧붙여 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "로그에서 확인한 두 서버의 스케줄러 동시 실행을 잠금 키 선택의 근거로 구체적으로 제시한다.",
            "잠금 키가 동시 실행을 제한해 같은 원인의 알림 중복 발송을 막는다는 연결을 타당하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "스케줄러의 중복 실행을 막으려고 잠금 키를 선택했다고 답하지만 로그에서 확인한 원인과의 연결이 일반적이다.",
            "잠금 키의 필요성을 설명하지만 두 서버의 동시 실행을 막는 데 적절한 이유를 충분히 뒷받침하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "잠금 키를 적용했다는 조치만 반복하고 선택 근거를 제시하지 못한다.",
            "알림 중복 발송의 확인된 원인과 무관한 근거를 제시하거나 잠금 키의 역할을 잘못 설명한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "현업·사용자 요청을 구현할 요구사항의 범위로 구체화할 수 있는지 확인한다. 요구사항 정의서 작성 경험에서 개발 담당 팀원과 범위를 조정한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 세탁소 5곳을 인터뷰했다.",
          "task": "기획 담당으로 요구사항 정의서를 작성하고 개발 담당 팀원과 범위를 조정했다.",
          "action": "인터뷰에서 파악한 요청을 구현 범위로 구체화할 때 어떤 근거로 범위를 조정했는지 설명한다.",
          "result": "제시한 근거가 개발 범위를 명확하게 정하는 데 어떤 의미가 있었는지 설명한다."
        },
        "expectedEvidence": [
          "개발 담당 팀원과 요구사항 범위를 조정한 판단 근거",
          "그 근거를 뒷받침하는 인터뷰 내용이나 프로젝트의 제약",
          "판단 근거와 실제 조정한 요구사항 범위의 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 개발 담당 팀원과 범위를 조정하셨을 때, 요구사항의 범위를 정한 근거는 무엇이었나요?",
      "answerTip": "핵심 답변부터 짧게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "사용자 요청의 목적이나 프로젝트 제약을 구체적으로 짚어 요구사항 범위를 정한 근거를 설명한다.",
            "제시한 근거가 실제로 조정한 요구사항의 범위와 명확하게 연결되어 개발할 대상을 구분할 수 있다."
          ]
        },
        "acceptable": {
          "criteria": [
            "요구사항 범위를 정한 근거를 제시하지만 중요도나 일정 등 일반적인 설명에 머문다.",
            "근거와 조정한 범위의 연결은 드러나지만 어떤 요청에 적용한 판단인지 구체성이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "요구사항 정의서를 작성했다거나 개발 담당 팀원과 논의했다는 사실만 말하고 범위를 정한 근거를 제시하지 않는다.",
            "제시한 근거가 사용자 요청이나 구현 범위와 연결되지 않아 범위 조정의 타당성을 확인할 수 없다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황에서 사용자에게 보일 화면의 반응을 구현 가능한 수준으로 설계할 수 있는지 확인한다. 예약 취소 실패 직후의 화면 상태와 안내를 하나의 화면 반응으로 구체화하는 데 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "입사 후 서비스의 예약 취소 실패 상황을 화면설계서로 만드는 상황이다.",
          "task": "예약 취소 실패 직후 사용자에게 보일 화면의 반응을 정한다.",
          "action": "취소 실패를 알리는 화면 상태와 안내를 구체적인 화면 반응으로 제안한다.",
          "result": "사용자가 취소 실패를 성공으로 오해하지 않고 화면에서 가능한 행동을 알 수 있을 것으로 예상한다."
        },
        "expectedEvidence": [
          "예약 취소 실패 직후 화면이 사용자에게 보일 구체적인 반응",
          "제안한 화면 반응에서 드러나는 취소 상태",
          "화면 반응에 포함된 안내나 조작 요소의 구체성"
        ]
      },
      "question": "입사 후 서비스의 예약 취소 실패 상황을 화면설계서로 만든다면, 실패 직후 화면이 사용자에게 보일 반응은 무엇인가요?",
      "answerTip": "떠올린 장면을 짧은 문장으로 말해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예약 취소 실패 직후의 화면 반응을 상태 표시나 안내 문구, 조작 요소 등으로 구체적으로 제안한다.",
            "제안한 화면 반응이 취소 실패 상태와 일치하며 사용자가 화면의 의미를 오해하지 않도록 명확하다."
          ]
        },
        "acceptable": {
          "criteria": [
            "실패 메시지 표시 등 상황에 맞는 화면 반응을 제안하지만 실제로 구현할 모습은 일부 불분명하다.",
            "취소 실패를 알리는 방향은 적절하지만 표시 내용이나 화면 요소의 반응이 포괄적인 수준에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "오류 원인 조사나 개발자 문의 등 다른 업무만 말하고 사용자에게 보일 화면 반응을 제안하지 않는다.",
            "취소 성공으로 표시하는 등 실패 상태와 모순되는 반응을 제안하거나 추상적인 표현만 반복한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "처방이 의심스러울 때 그대로 투약하지 않고 확인하는 행동을 평가한다. 진통제 투약을 멈추고 담당의에게 확인하기로 한 판단 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 정형외과 병동 근무 중 수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어왔다.",
          "task": "수술 후 환자의 투약·처치를 담당했으며, 진통제를 투약하기 전이었다.",
          "action": "평소 용량과 다른 처방을 보고 투약을 멈춘 판단 근거와 담당의 확인이 필요하다고 본 이유를 설명한다.",
          "result": "담당의 확인 결과 입력 오류였다는 사실이 당시 판단 근거와 어떤 관계가 있는지 설명한다."
        },
        "expectedEvidence": [
          "투약을 멈추고 담당의에게 확인하기로 한 판단 근거",
          "처방 용량이 평소 용량의 두 배였다는 차이를 해석한 내용",
          "담당의 확인 전에는 처방의 정확성을 확신할 수 없었다는 설명"
        ]
      },
      "question": "푸른결종합병원에서 진통제 처방 용량이 평소의 두 배로 들어왔을 때, 투약을 멈추고 담당의에게 확인하기로 판단하신 근거는 무엇이었나요?",
      "answerTip": "본인이 한 일을 중심으로 짧게 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "평소 용량의 두 배라는 차이를 처방의 정확성을 확인해야 할 구체적인 근거로 설명한다.",
            "확인되지 않은 용량을 그대로 투약할 위험과 연결해, 담당의 확인 전 투약을 멈춘 판단을 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "평소와 용량이 달라 확인이 필요했다고 답하지만, 그 차이를 의심한 근거가 구체적이지 않다.",
            "환자 안전이나 처방 확인 원칙을 들어 투약 중단을 설명하지만, 당시 처방과의 연결이 제한적이다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈추고 담당의에게 확인한 이유를 말하지 않고 조치나 결과만 반복한다.",
            "처방 용량의 차이와 무관한 일반론을 말하거나, 확인 없이 투약해도 된다는 판단을 제시한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰한 환자 상태의 이상 징후를 담당 의사에게 전달하는 행동을 평가한다. 의식 수준의 변화를 알아볼 수 있게 처음 보고할 말을 구성하는 데 초점을 둔다.",
        "questionType": "situational",
        "expectedSTAR": {
          "situation": "입사 후 병동에서 수술 후 환자의 의식 수준이 평소보다 떨어진 것을 관찰한 상황이다.",
          "task": "관찰한 의식 수준의 변화를 담당 의사에게 보고해야 한다.",
          "action": "어느 환자에 관한 보고인지 밝히고, 평소와 비교해 의식 수준이 떨어졌다는 관찰 사실을 전달하는 첫 보고 문장을 제시한다.",
          "result": "담당 의사가 보고 대상과 의식 수준의 변화를 바로 알아볼 수 있을 것으로 예상한다."
        },
        "expectedEvidence": [
          "담당 의사에게 처음 보고할 실제 문장",
          "보고 문장에 드러난 평소 상태와 관찰한 의식 수준의 차이"
        ]
      },
      "question": "입사 후 병동에서 수술 후 환자의 의식 수준이 평소보다 떨어진 것을 관찰한다면, 담당 의사에게 처음 보고할 말은 무엇인가요?",
      "answerTip": "말할 내용을 자연스러운 문장으로 답해 주세요.",
